#include <iostream>

struct Key { int group; int id; };

int main() {
  const auto comp = [](const Key& a, const Key& b) {
    return a.group < b.group;
  };
  Key a{2, 10}, b{2, 99};
  bool ab = comp(a, b);
  bool ba = comp(b, a);
  std::cout << ab << ' ' << ba << ' '
            << (!ab && !ba);
}
